import Button from '@jetbrains/ring-ui-built/components/button/button'
import type * as React from 'react'

import ExpandablePanel from '../../../components/ExpandablePanel/ExpandablePanel'
import styles from '../AgentBuildTypes.module.css'
import type {
  AgentBuildTypesFlatTree,
  AgentBuildTypesTreeBuildTypeItem,
  AgentBuildTypesTreeProjectItem,
} from '../AgentBuildTypes.types'
import AgentBuildTypesTree from '../Tree/AgentBuildTypesTree'

type BuildTypesSectionProps = {
  heading: React.ReactNode
  flatTree: AgentBuildTypesFlatTree
  expanded: boolean
  setExpandState: (arg0: {id: string; expanded: boolean}) => void
  assignAll?: (arg0: void) => void
  unassignAll?: (arg0: void) => void
  assignProject?: (node: AgentBuildTypesTreeProjectItem) => void
  unassignProject?: (node: AgentBuildTypesTreeProjectItem) => void
  assignBuildType?: (node: AgentBuildTypesTreeBuildTypeItem) => void
  unassignBuildType?: (node: AgentBuildTypesTreeBuildTypeItem) => void
}

function BuildTypesSection({
  heading,
  flatTree,
  expanded,
  setExpandState,
  assignAll,
  unassignAll,
  assignProject,
  unassignProject,
  assignBuildType,
  unassignBuildType,
}: BuildTypesSectionProps) {
  let subheading

  if (expanded && unassignAll != null && assignAll == null) {
    subheading = (
      <Button
        inline
        className={styles.assignmentAction}
        onClick={e => {
          unassignAll()
          e.stopPropagation()
        }}
      >
        {'Unassign all'}
      </Button>
    )
  }

  return (
    <ExpandablePanel
      className={styles.section}
      headerClassName={styles.sectionHeader}
      heading={heading}
      subheading={subheading}
      content={
        <AgentBuildTypesTree
          flatTree={flatTree}
          onToggleExpand={setExpandState}
          assignProject={assignProject}
          unassignProject={unassignProject}
          assignBuildType={assignBuildType}
          unassignBuildType={unassignBuildType}
        />
      }
      expanded={expanded}
    />
  )
}

export default BuildTypesSection
