import searchIcon from '@jetbrains/icons/search.svg'
import alert from '@jetbrains/ring-ui-built/components/alert-service/alert-service'
import Checkbox from '@jetbrains/ring-ui-built/components/checkbox/checkbox'
import * as React from 'react'
import {graphql, useLazyLoadQuery, useMutation} from 'react-relay'
import type {RecordSourceSelectorProxy} from 'relay-runtime'
import type {SelectorStoreUpdater} from 'relay-runtime/lib/store/RelayStoreTypes'

import {useAgentId} from '../../../../../hooks/routes'
import {stringifyId} from '../../../../../types'
import ExpandablePanel from '../../components/ExpandablePanel/ExpandablePanel'
import Search from '../../components/Search/Search'

import type {
  AgentBuildTypesAssignBuildTypeMutation,
  AgentBuildTypesAssignBuildTypeMutation$data,
} from './__generated__/AgentBuildTypesAssignBuildTypeMutation.graphql'
import type {
  AgentBuildTypesAssignProjectBuildTypesMutation,
  AgentBuildTypesAssignProjectBuildTypesMutation$data,
} from './__generated__/AgentBuildTypesAssignProjectBuildTypesMutation.graphql'
import type {
  AgentBuildTypesAssociatedQuery$data,
  AgentBuildTypesAssociatedQuery,
} from './__generated__/AgentBuildTypesAssociatedQuery.graphql'
import type {AgentBuildTypesDissociatedQuery} from './__generated__/AgentBuildTypesDissociatedQuery.graphql'
import type {
  AgentBuildTypesSetAgentRunScopeMutation,
  AgentBuildTypesSetAgentRunScopeMutation$data,
} from './__generated__/AgentBuildTypesSetAgentRunScopeMutation.graphql'
import type {
  AgentBuildTypesUnassignAllAgentBuildTypesMutation,
  AgentBuildTypesUnassignAllAgentBuildTypesMutation$data,
} from './__generated__/AgentBuildTypesUnassignAllAgentBuildTypesMutation.graphql'
import type {
  AgentBuildTypesUnassignBuildTypeMutation,
  AgentBuildTypesUnassignBuildTypeMutation$data,
} from './__generated__/AgentBuildTypesUnassignBuildTypeMutation.graphql'
import type {
  AgentBuildTypesUnassignProjectBuildTypesMutation,
  AgentBuildTypesUnassignProjectBuildTypesMutation$data,
} from './__generated__/AgentBuildTypesUnassignProjectBuildTypesMutation.graphql'
import {createFlatAgentBuildTypesTree} from './AgentBuildTypes.selectors'
import type {
  AgentBuildTypesTreeExpandState,
  AgentResponseBuildTypeEdges,
} from './AgentBuildTypes.types'
import BuildTypesSection from './BuildTypesSection/BuildTypesSection'
import AgentBuildTypesTree from './Tree/AgentBuildTypesTree'

import styles from './AgentBuildTypes.module.css'

const agentAssociatedBuildTypesQuery = graphql`
  query AgentBuildTypesAssociatedQuery($id: ID!, $compatible: Boolean) {
    agent(id: $id) {
      id
      rawId
      associatedBuildTypes(filter: {compatible: $compatible}) {
        runPolicy
        edges {
          node {
            id
            rawId
            name
            type
            ancestorProjects {
              edges {
                node {
                  id
                  rawId
                  name
                }
              }
            }
          }
          assigned
          incompatibilities {
            typename: __typename
            ... on RunnerAgentBuildTypeIncompatibility {
              displayName
            }
            ... on UnmetRequirementAgentBuildTypeIncompatibility {
              propertyName
              propertyValue
              type
            }
            ... on UndefinedRunParameterAgentBuildTypeIncompatibility {
              name
              origin
            }
          }
        }
      }
    }
  }
`
const agentDissociatedBuildTypesQuery = graphql`
  query AgentBuildTypesDissociatedQuery($id: ID!, $compatible: Boolean) {
    agent(id: $id) {
      id
      rawId
      dissociatedBuildTypes(filter: {compatible: $compatible}) {
        edges {
          node {
            id
            rawId
            name
            type
            ancestorProjects {
              edges {
                node {
                  id
                  rawId
                  name
                }
              }
            }
          }
          assigned
          incompatibilities {
            typename: __typename
            ... on RunnerAgentBuildTypeIncompatibility {
              displayName
            }
            ... on UnmetRequirementAgentBuildTypeIncompatibility {
              propertyName
              propertyValue
              type
            }
            ... on UndefinedRunParameterAgentBuildTypeIncompatibility {
              name
              origin
            }
          }
        }
      }
    }
  }
`
const setAgentRunPolicyMutation = graphql`
  mutation AgentBuildTypesSetAgentRunScopeMutation(
    $agentRawId: ID!
    $agentRunPolicy: AgentRunPolicy
  ) @raw_response_type {
    setAgentRunPolicy(input: {agentRawId: $agentRawId, agentRunPolicy: $agentRunPolicy}) {
      agent {
        id
        associatedBuildTypes {
          runPolicy
        }
      }
    }
  }
`
const assignBuildTypeMutation = graphql`
  mutation AgentBuildTypesAssignBuildTypeMutation($agentRawId: ID!, $buildTypeRawId: ID!)
  @raw_response_type {
    assignBuildTypeWithAgent(input: {agentRawId: $agentRawId, buildTypeRawId: $buildTypeRawId}) {
      agent {
        id
      }
    }
  }
`
const assignProjectBuildTypesMutation = graphql`
  mutation AgentBuildTypesAssignProjectBuildTypesMutation($agentRawId: ID!, $projectRawId: ID!)
  @raw_response_type {
    assignProjectBuildTypesWithAgent(
      input: {agentRawId: $agentRawId, projectRawId: $projectRawId}
    ) {
      agent {
        id
      }
    }
  }
`
const unassignProjectBuildTypesMutation = graphql`
  mutation AgentBuildTypesUnassignProjectBuildTypesMutation($agentRawId: ID!, $projectRawId: ID!)
  @raw_response_type {
    unassignProjectBuildTypesFromAgent(
      input: {agentRawId: $agentRawId, projectRawId: $projectRawId}
    ) {
      agent {
        id
      }
    }
  }
`
const unassignBuildTypesMutation = graphql`
  mutation AgentBuildTypesUnassignAllAgentBuildTypesMutation($agentRawId: ID!) @raw_response_type {
    unassignAllAgentBuildTypes(input: {agentRawId: $agentRawId}) {
      agent {
        id
      }
    }
  }
`
const unassignBuildTypeMutation = graphql`
  mutation AgentBuildTypesUnassignBuildTypeMutation($agentRawId: ID!, $buildTypeRawId: ID!)
  @raw_response_type {
    unassignBuildTypeFromAgent(input: {agentRawId: $agentRawId, buildTypeRawId: $buildTypeRawId}) {
      agent {
        id
        rawId
      }
    }
  }
`
type ExpandStateReducedAction = {
  id: string
  expanded: boolean
}

const expandStateReducer = (
  state: AgentBuildTypesTreeExpandState,
  {id, expanded}: ExpandStateReducedAction,
): AgentBuildTypesTreeExpandState => ({...state, [id]: expanded})

function splitAssignedBuildTypes$data({
  agent,
}: AgentBuildTypesAssociatedQuery$data): [
  AgentResponseBuildTypeEdges,
  AgentResponseBuildTypeEdges,
] {
  const emptyResult: [AgentResponseBuildTypeEdges, AgentResponseBuildTypeEdges] = [[], []]

  if (agent == null) {
    return emptyResult
  }

  const {associatedBuildTypes} = agent

  if (associatedBuildTypes == null) {
    return emptyResult
  }

  const {edges} = associatedBuildTypes
  return [edges.filter(edge => edge.assigned), edges.filter(edge => !edge.assigned)]
}

type Props = {
  agentRawId: string
  searchQuery: string
}
const COMPATIBLE_BUILD_TYPES_RECORD_KEY =
  'buildTypes(filter:{"byAgentPoolRelation":{"assigned":true},"byAgentRelation":{"compatible":true}})'
const INCOMPATIBLE_BUILD_TYPES_RECORD_KEY =
  'buildTypes(filter:{"byAgentPoolRelation":{"assigned":true},"byAgentRelation":{"compatible":false}})'
const BUILD_TYPES_FROM_OTHER_POOLS_RECORD_KEY =
  'buildTypes(filter:{"byAgentPoolRelation":{"assigned":false},"byAgentRelation":{"compatible":null}})'

function findAgentBuildTypes(
  store: RecordSourceSelectorProxy,
  buildTypesKey: string,
  agentId: string,
) {
  return store.get(agentId)?.getLinkedRecord(buildTypesKey)?.getLinkedRecords('edges')
}

function findAgentBuildType(
  store: RecordSourceSelectorProxy,
  agentId: string,
  buildTypesKey: string,
  buildTypeId: string,
) {
  return findAgentBuildTypes(store, buildTypesKey, agentId)?.find(
    edge => edge?.getLinkedRecord('node')?.getValue('id') === buildTypeId,
  )
}

function findProjectBuildTypes(
  store: RecordSourceSelectorProxy,
  buildTypesKey: string,
  agentId: string,
  projectId: string,
) {
  return findAgentBuildTypes(store, buildTypesKey, agentId)?.filter(edge =>
    edge
      ?.getLinkedRecord('node')
      ?.getLinkedRecord('ancestorProjects')
      ?.getLinkedRecords('edges')
      ?.find(projectEdge => projectEdge?.getLinkedRecord('node')?.getValue('id') === projectId),
  )
}

const onError = (e: Error) => {
  alert.error(e.message)
}

function AgentCompatibleBuildTypes({agentRawId, searchQuery}: Props) {
  const [expandState, setExpandState] = React.useReducer(expandStateReducer, {})
  const props = useLazyLoadQuery<AgentBuildTypesAssociatedQuery>(
    agentAssociatedBuildTypesQuery,
    {
      id: agentRawId,
      compatible: true,
    },
    {fetchPolicy: 'store-and-network'},
  )
  const [setAgentRunPolicy] =
    useMutation<AgentBuildTypesSetAgentRunScopeMutation>(setAgentRunPolicyMutation)
  const [unassignBuildTypes] = useMutation<AgentBuildTypesUnassignAllAgentBuildTypesMutation>(
    unassignBuildTypesMutation,
  )
  const [unassignProjectBuildTypes] = useMutation<AgentBuildTypesUnassignProjectBuildTypesMutation>(
    unassignProjectBuildTypesMutation,
  )
  const [unassignBuildTypeFromAgent] =
    useMutation<AgentBuildTypesUnassignBuildTypeMutation>(unassignBuildTypeMutation)
  const [assignProjectBuildTypes] = useMutation<AgentBuildTypesAssignProjectBuildTypesMutation>(
    assignProjectBuildTypesMutation,
  )
  const [assignBuildType] =
    useMutation<AgentBuildTypesAssignBuildTypeMutation>(assignBuildTypeMutation)

  const {agent} = props

  if (agent == null) {
    return <div>{'Agent was not found'}</div>
  }

  if (agent.associatedBuildTypes == null) {
    throw new Error(
      'Missing `associatedBuildTypes` property in the Agent type. Check GraphQL API version',
    )
  }

  const agentRunScope = agent.associatedBuildTypes.runPolicy
  const runAssignedBuildTypes = agentRunScope === 'ASSIGNED'
  const oppositeAgentRunScope = runAssignedBuildTypes ? 'ALL' : 'ASSIGNED'
  const [assignedBuildTypes, unassignedBuildTypes] = splitAssignedBuildTypes$data(props)

  if (assignedBuildTypes == null || unassignedBuildTypes == null) {
    throw new Error(
      'Missing `associatedBuildTypes` property in the Agent type. Check GraphQL API version',
    )
  }

  const setRunScopeUpdater: SelectorStoreUpdater<
    AgentBuildTypesSetAgentRunScopeMutation$data
  > = proxyStore => {
    proxyStore
      .get(agent.id)
      ?.getLinkedRecord(COMPATIBLE_BUILD_TYPES_RECORD_KEY)
      ?.setValue(oppositeAgentRunScope, 'runPolicy')
  }

  return (
    <div>
      <Checkbox
        checked={runAssignedBuildTypes}
        onChange={() => {
          setAgentRunPolicy({
            variables: {
              agentRawId,
              agentRunPolicy: oppositeAgentRunScope,
            },
            optimisticResponse: {
              setAgentRunPolicy: {
                agent: {
                  associatedBuildTypes: {runPolicy: oppositeAgentRunScope},
                  id: agent.id,
                },
              },
            },
            optimisticUpdater: setRunScopeUpdater,
            updater: setRunScopeUpdater,
            onError,
          })
        }}
      >
        {'Run assigned configurations only'}
      </Checkbox>
      {runAssignedBuildTypes ? (
        <>
          <BuildTypesSection
            heading={'Assigned compatible configurations'}
            flatTree={createFlatAgentBuildTypesTree(assignedBuildTypes, expandState, searchQuery)}
            setExpandState={setExpandState}
            unassignAll={() => {
              const unassignBuildTypesUpdater: SelectorStoreUpdater<
                AgentBuildTypesUnassignAllAgentBuildTypesMutation$data
              > = store => {
                findAgentBuildTypes(store, COMPATIBLE_BUILD_TYPES_RECORD_KEY, agent.id)?.forEach(
                  record => record?.setValue(false, 'assigned'),
                )
              }

              unassignBuildTypes({
                variables: {
                  agentRawId,
                },
                optimisticResponse: {
                  unassignAllAgentBuildTypes: {agent: {id: agent.id}},
                },
                optimisticUpdater: unassignBuildTypesUpdater,
                updater: unassignBuildTypesUpdater,
                onError,
              })
            }}
            unassignProject={projectNode => {
              const unassignProjectBuildTypesUpdater: SelectorStoreUpdater<
                AgentBuildTypesUnassignProjectBuildTypesMutation$data
              > = store => {
                findProjectBuildTypes(
                  store,
                  COMPATIBLE_BUILD_TYPES_RECORD_KEY,
                  agent.id,
                  stringifyId(projectNode.id),
                )?.forEach(record => record?.setValue(false, 'assigned'))
              }

              unassignProjectBuildTypes({
                variables: {
                  agentRawId,
                  projectRawId: projectNode.rawId, // !
                },
                optimisticResponse: {
                  unassignProjectBuildTypesFromAgent: {agent: {id: agent.id}},
                },
                optimisticUpdater: unassignProjectBuildTypesUpdater,
                updater: unassignProjectBuildTypesUpdater,
                onError,
              })
            }}
            unassignBuildType={buildTypeNode => {
              const unassignBuildTypeUpdater: SelectorStoreUpdater<
                AgentBuildTypesUnassignBuildTypeMutation$data
              > = store => {
                findAgentBuildType(
                  store,
                  agent.id,
                  COMPATIBLE_BUILD_TYPES_RECORD_KEY,
                  stringifyId(buildTypeNode.id),
                )?.setValue(false, 'assigned')
              }

              unassignBuildTypeFromAgent({
                variables: {agentRawId: agent.id, buildTypeRawId: buildTypeNode.rawId},
                optimisticUpdater: unassignBuildTypeUpdater,
                updater: unassignBuildTypeUpdater,
                onError,
              })
            }}
            expanded
          />
          <BuildTypesSection
            heading={'Unassigned compatible configurations'}
            flatTree={createFlatAgentBuildTypesTree(unassignedBuildTypes, expandState, searchQuery)}
            setExpandState={setExpandState}
            assignProject={projectNode => {
              const assignProjectBuildTypesUpdater: SelectorStoreUpdater<
                AgentBuildTypesAssignProjectBuildTypesMutation$data
              > = store => {
                findProjectBuildTypes(
                  store,
                  COMPATIBLE_BUILD_TYPES_RECORD_KEY,
                  agent.id,
                  stringifyId(projectNode.id),
                )?.forEach(record => record?.setValue(true, 'assigned'))
              }

              assignProjectBuildTypes({
                variables: {
                  agentRawId,
                  projectRawId: projectNode.rawId,
                },
                optimisticResponse: {
                  assignProjectBuildTypesWithAgent: {agent: {id: agent.id}},
                },
                optimisticUpdater: assignProjectBuildTypesUpdater,
                updater: assignProjectBuildTypesUpdater,
                onError,
              })
            }}
            assignBuildType={buildTypeNode => {
              const assignBuildTypeUpdater: SelectorStoreUpdater<
                AgentBuildTypesAssignBuildTypeMutation$data
              > = store => {
                findAgentBuildType(
                  store,
                  agent.id,
                  COMPATIBLE_BUILD_TYPES_RECORD_KEY,
                  buildTypeNode.id,
                )?.setValue(true, 'assigned')
              }

              assignBuildType({
                variables: {
                  agentRawId,
                  buildTypeRawId: buildTypeNode.rawId,
                },
                optimisticResponse: {
                  assignBuildTypeWithAgent: {agent: {id: agent.id}},
                },
                optimisticUpdater: assignBuildTypeUpdater,
                updater: assignBuildTypeUpdater,
                onError,
              })
            }}
            expanded
          />
        </>
      ) : props.agent?.associatedBuildTypes != null ? (
        <BuildTypesSection
          heading={'Compatible configurations'}
          flatTree={createFlatAgentBuildTypesTree(
            props.agent.associatedBuildTypes.edges,
            expandState,
            searchQuery,
          )}
          setExpandState={setExpandState}
          expanded
        />
      ) : null}
    </div>
  )
}

function AgentIncompatibleBuildTypes({agentRawId, searchQuery}: Props) {
  const [expandState, setExpandState] = React.useReducer(expandStateReducer, {})
  const {agent} = useLazyLoadQuery<AgentBuildTypesAssociatedQuery>(
    agentAssociatedBuildTypesQuery,
    {
      id: agentRawId,
      compatible: false,
    },
    {fetchPolicy: 'store-and-network'},
  )
  const [unassignBuildTypeFromAgent] =
    useMutation<AgentBuildTypesUnassignBuildTypeMutation>(unassignBuildTypeMutation)

  return (
    <ExpandablePanel
      className={styles.section}
      headerClassName={styles.sectionHeader}
      heading={'Incompatible configurations'}
      content={
        agent?.associatedBuildTypes == null ? null : (
          <AgentBuildTypesTree
            flatTree={createFlatAgentBuildTypesTree(
              agent.associatedBuildTypes.edges,
              expandState,
              searchQuery,
            )}
            onToggleExpand={setExpandState}
            unassignBuildType={buildTypeNode => {
              const unassignBuildTypeUpdater: SelectorStoreUpdater<
                AgentBuildTypesUnassignBuildTypeMutation$data
              > = store => {
                findAgentBuildType(
                  store,
                  agent.id,
                  INCOMPATIBLE_BUILD_TYPES_RECORD_KEY,
                  stringifyId(buildTypeNode.id),
                )?.setValue(false, 'assigned')
              }

              unassignBuildTypeFromAgent({
                variables: {agentRawId, buildTypeRawId: buildTypeNode.rawId},
                optimisticUpdater: unassignBuildTypeUpdater,
                updater: unassignBuildTypeUpdater,
                onError,
              })
            }}
          />
        )
      }
      expanded
    />
  )
}

function BuildTypesFromOtherPools({agentRawId, searchQuery}: Props) {
  const [expandState, setExpandState] = React.useReducer(expandStateReducer, {})
  const {agent} = useLazyLoadQuery<AgentBuildTypesDissociatedQuery>(
    agentDissociatedBuildTypesQuery,
    {
      id: agentRawId,
    },
  )
  const [unassignBuildTypeFromAgent] =
    useMutation<AgentBuildTypesUnassignBuildTypeMutation>(unassignBuildTypeMutation)

  return (
    <ExpandablePanel
      className={styles.section}
      headerClassName={styles.sectionHeader}
      heading={'Configurations from other pools'}
      content={
        agent?.dissociatedBuildTypes == null ? null : (
          <AgentBuildTypesTree
            flatTree={createFlatAgentBuildTypesTree(
              agent.dissociatedBuildTypes.edges,
              expandState,
              searchQuery,
            )}
            onToggleExpand={setExpandState}
            unassignBuildType={buildTypeNode => {
              const unassignBuildTypeUpdater: SelectorStoreUpdater<
                AgentBuildTypesUnassignBuildTypeMutation$data
              > = store => {
                findAgentBuildType(
                  store,
                  agent.id,
                  BUILD_TYPES_FROM_OTHER_POOLS_RECORD_KEY,
                  stringifyId(buildTypeNode.id),
                )?.setValue(false, 'assigned')
              }

              unassignBuildTypeFromAgent({
                variables: {agentRawId, buildTypeRawId: buildTypeNode.rawId},
                optimisticUpdater: unassignBuildTypeUpdater,
                updater: unassignBuildTypeUpdater,
                onError,
              })
            }}
          />
        )
      }
      expanded
    />
  )
}

function AgentBuildTypes() {
  const [searchQuery, setSearchQuery] = React.useState('')
  const agentRawId = stringifyId(useAgentId())

  if (agentRawId == null) {
    return null
  }

  return (
    <div className={styles.agentBuildTypesTab}>
      <Search
        onChange={e => {
          setSearchQuery(e.target.value)
        }}
        onClear={() => {
          setSearchQuery('')
        }}
        className={styles.search}
        placeholder="Search project or configuration"
        icon={searchIcon}
        value={searchQuery}
      />
      <AgentCompatibleBuildTypes agentRawId={agentRawId} searchQuery={searchQuery} />
      <AgentIncompatibleBuildTypes agentRawId={agentRawId} searchQuery={searchQuery} />
      <BuildTypesFromOtherPools agentRawId={agentRawId} searchQuery={searchQuery} />
    </div>
  )
}

export default AgentBuildTypes
