import memoizeOne from 'memoize-one'

import {ROOT_PROJECT_ID, stringifyId, toBuildTypeId, toProjectId} from '../../../../../types'
import type {ProjectId, Id} from '../../../../../types'
import {emptyArray} from '../../../../../utils/empty'

import type {
  AgentBuildTypesAgentBuildTypesTreeNode,
  AgentBuildTypesFlatTree,
  AgentBuildTypesTreeExpandState,
  AgentBuildTypesTreeProjectNode,
  AgentBuildTypesTree,
  AgentResponseBuildTypeEdges,
} from './AgentBuildTypes.types'

function createAgentBuildTypesTree(edges: AgentResponseBuildTypeEdges): AgentBuildTypesTree {
  const projectsHash: Record<ProjectId, AgentBuildTypesTreeProjectNode> = {}
  const rootProjects: Array<AgentBuildTypesTreeProjectNode> = []
  edges.forEach(buildTypeEdge => {
    if (buildTypeEdge.node != null) {
      const {id, rawId, name, ancestorProjects, type} = buildTypeEdge.node

      if (name == null) {
        throw new Error('Missing `name` property in the Agent type. Check GraphQL API version')
      }

      let treeChildNode: AgentBuildTypesAgentBuildTypesTreeNode | null | undefined = {
        id: toBuildTypeId(id),
        rawId,
        name,
        type: 'build-type',
        composite: type === 'COMPOSITE',
        assigned: buildTypeEdge.assigned,
        incompatibilities: buildTypeEdge.incompatibilities,
      }
      ancestorProjects?.edges.forEach(projectEdge => {
        if (projectEdge.node != null) {
          const {node: projectNode} = projectEdge
          const projectId = toProjectId(projectNode.id)

          if (projectNode.name == null) {
            throw new Error(
              'Missing `name` property in the Project type. Check GraphQL API version',
            )
          }

          if (projectId === ROOT_PROJECT_ID && treeChildNode?.type === 'project') {
            rootProjects.push(treeChildNode)
            return
          }

          if (projectsHash[projectId] == null) {
            projectsHash[projectId] = {
              children: treeChildNode == null ? [] : [treeChildNode],
              id: projectId,
              rawId: projectNode.rawId,
              name: projectNode.name,
              type: 'project',
            }
            treeChildNode = projectsHash[projectId]
          } else {
            if (treeChildNode != null) {
              projectsHash[projectId].children.push(treeChildNode)
            }

            treeChildNode = null
          }
        }
      })
    }
  })
  return rootProjects
}

function generateUniqueId(uniqueParentInternalId: string, id: Id): string {
  return `${uniqueParentInternalId !== '' ? `${uniqueParentInternalId}-` : ''}${stringifyId(
    id,
  ).replace(/(\(|\))/, '')}`
}

const matchTitle = (title: string, searchQuery: string) =>
  title.toLowerCase().includes(searchQuery.trim().toLowerCase())

function flattenProjectNode(
  projectNode: AgentBuildTypesTreeProjectNode,
  expandState: AgentBuildTypesTreeExpandState,
  searchQuery: string,
  level = 0,
  uniqueParentInternalId = '',
): AgentBuildTypesFlatTree {
  const {id, children, name, ...rest} = projectNode
  const uniqueId = generateUniqueId(uniqueParentInternalId, id)
  const expanded = expandState[toProjectId(uniqueId)] !== false
  const projectIsMatching = matchTitle(name, searchQuery)
  let hasAssigned = false
  let hasMatching = false
  const childNodes = expanded
    ? children.flatMap(childNode => {
        let flatProjectSubtree

        if (childNode.type === 'project') {
          flatProjectSubtree = flattenProjectNode(
            childNode,
            expandState,
            searchQuery,
            level + 1,
            uniqueId,
          )
        } else {
          const buildTypeIsMatching = matchTitle(childNode.name, searchQuery)
          flatProjectSubtree = buildTypeIsMatching
            ? [
                {
                  ...childNode,
                  matching: matchTitle(childNode.name, searchQuery),
                  uniqueId: generateUniqueId(uniqueId, childNode.id),
                  level: level + 1,
                },
              ]
            : emptyArray
        }

        if (!hasAssigned && childNode.type === 'build-type' && childNode.assigned === true) {
          hasAssigned = true
        }

        if (!hasMatching && flatProjectSubtree[0]?.matching) {
          hasMatching = true
        }

        return flatProjectSubtree
      })
    : []
  return projectIsMatching || hasMatching
    ? [
        {
          id,
          uniqueId,
          name,
          ...rest,
          level,
          expanded,
          empty: children.length === 0,
          hasAssigned,
          hasMatching,
          matching: projectIsMatching,
        },
        ...childNodes,
      ]
    : emptyArray
}

export const createFlatAgentBuildTypesTree = memoizeOne(
  (
    edges: AgentResponseBuildTypeEdges,
    expandState: AgentBuildTypesTreeExpandState,
    searchQuery = '',
  ): AgentBuildTypesFlatTree =>
    createAgentBuildTypesTree(edges).flatMap(projectNode =>
      flattenProjectNode(projectNode, expandState, searchQuery),
    ),
)
