import buildType12pxIcon from '@jetbrains/icons/buildType-12px.svg'
import buildTypeComposite12pxIcon from '@jetbrains/icons/buildType-composite-12px.svg'
import project12pxIcon from '@jetbrains/icons/project-12px.svg'
import Button from '@jetbrains/ring-ui-built/components/button/button'
import Dropdown, {Anchor} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Popup from '@jetbrains/ring-ui-built/components/popup/popup'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import {getBuildTypeHref, getProjectHref} from '../../../../../../routes'
import Link from '../../../../../common/RouterLink/RouterLink'
import type {
  AgentBuildTypeIncompatibilityType,
  AgentBuildTypesFlatTree,
  AgentBuildTypesTreeBuildTypeItem,
  AgentBuildTypesTreeProjectItem,
} from '../AgentBuildTypes.types'

import styles from './AgentBuildTypesTree.module.css'

const TREE_LEFT_PADDING = 32
const TREE_ITEM_LEFT_PADDING = 16
const BUILD_TYPE_LEFT_PADDING = 16

function getLevelPadding(level: number): number {
  return TREE_LEFT_PADDING + level * TREE_ITEM_LEFT_PADDING
}

type AgentBuildTypeProjectProps = {
  node: AgentBuildTypesTreeProjectItem
  onToggleExpand: (arg0: {id: string; expanded: boolean}) => void
  onAssign?: (node: AgentBuildTypesTreeProjectItem) => void
  onUnassign?: (node: AgentBuildTypesTreeProjectItem) => void
}

function AgentBuildTypesTreeProject({
  node,
  onToggleExpand,
  onAssign,
  onUnassign,
}: AgentBuildTypeProjectProps) {
  const onToggle = React.useCallback(() => {
    onToggleExpand({
      id: node.uniqueId,
      expanded: !node.expanded,
    })
  }, [node, onToggleExpand])
  return (
    <div
      className={classNames(styles.item, styles.projectItem)}
      style={{
        paddingLeft: `${getLevelPadding(node.level)}px`,
      }}
      role="button"
      tabIndex={0}
      onKeyDown={onToggle}
      onClick={onToggle}
    >
      <div className={styles.itemLeftColumn}>
        <div className={styles.itemName}>
          <SvgIcon
            className={classNames(styles.itemTypeIcon, styles.chevronIcon, {
              [styles.disabledIcon]: node.empty,
            })}
            title={node.expanded ? 'Collapse' : 'Expand'}
            icon={node.expanded ? 'chevron-down' : 'chevron-right'}
          />
          <SvgIcon
            className={classNames(styles.itemTypeIcon)}
            title={'Project'}
            icon={project12pxIcon}
          />
          <Link to={getProjectHref(node.id)}>{node.name}</Link>
        </div>
      </div>
      {onAssign != null ? (
        <Button
          inline
          className={styles.assignItemButton}
          onClick={e => {
            onAssign(node)
            e.stopPropagation()
          }}
        >
          {'Assign'}
        </Button>
      ) : null}
      {onUnassign != null && node.hasAssigned != null && onAssign == null ? (
        <Button
          inline
          className={styles.assignItemButton}
          onClick={e => {
            onUnassign(node)
            e.stopPropagation()
          }}
        >
          {'Unassign'}
        </Button>
      ) : null}
    </div>
  )
}

function AgentBuildTypeIncompatibility({
  incompatibility,
  className,
}: {
  incompatibility: AgentBuildTypeIncompatibilityType
  className?: string
}) {
  if (incompatibility.typename === 'RunnerAgentBuildTypeIncompatibility') {
    return (
      <span className={classNames(className, styles.incompatibility)}>
        {'Incompatible runner: '}
        <span className={styles.incompatibilityPropName}>{incompatibility.displayName}</span>
      </span>
    )
  }

  if (incompatibility.typename === 'UnmetRequirementAgentBuildTypeIncompatibility') {
    const {type} = incompatibility

    if (type == null) {
      throw new Error(
        'Missing `type` property in the UnmetRequirementAgentBuildTypeIncompatibility type. Check GraphQL API version',
      )
    }

    return (
      <span className={classNames(className, styles.incompatibility)}>
        {'Unmet requirement: '}
        <span className={styles.incompatibilityPropName}>{incompatibility.propertyName}</span>{' '}
        <span>{type.toLowerCase()}</span>{' '}
        <span className={styles.incompatibilityPropValue}>{incompatibility.propertyValue}</span>
      </span>
    )
  }

  if (incompatibility.typename === 'UndefinedRunParameterAgentBuildTypeIncompatibility') {
    return (
      <span className={classNames(className, styles.incompatibility)}>
        {'Implicit requirement: '}
        <span className={styles.incompatibilityPropName}>{incompatibility.name}</span>
        {' defined in '}
        <span className={styles.incompatibilityPropName}>{incompatibility.origin}</span>
      </span>
    )
  }

  return null
}

type AgentBuildTypeProps = {
  node: AgentBuildTypesTreeBuildTypeItem
  onAssign?: (node: AgentBuildTypesTreeBuildTypeItem) => void
  onUnassign?: (node: AgentBuildTypesTreeBuildTypeItem) => void
}
const INCOMPATIBILITIES_POPUP_DIRECTIONS = [
  Popup.PopupProps.Directions.BOTTOM_CENTER,
  Popup.PopupProps.Directions.BOTTOM_LEFT,
]

function AgentBuildType({node, onAssign, onUnassign}: AgentBuildTypeProps) {
  const {level, composite, id, name, incompatibilities, assigned} = node
  const firstIncompatibility = incompatibilities != null ? incompatibilities[0] : null // hi flow

  return (
    <div
      className={styles.item}
      style={{
        paddingLeft: `${BUILD_TYPE_LEFT_PADDING + getLevelPadding(level)}px`,
      }}
    >
      <div className={styles.itemLeftColumn}>
        <span className={styles.itemName}>
          <SvgIcon
            className={styles.itemTypeIcon}
            title={'Build configuration'}
            icon={composite ? buildTypeComposite12pxIcon : buildType12pxIcon}
          />
          <Link className={styles.itemLink} to={getBuildTypeHref(id)}>
            {name}
          </Link>
        </span>
        {incompatibilities != null && firstIncompatibility != null ? (
          <>
            <AgentBuildTypeIncompatibility
              key={JSON.stringify(firstIncompatibility)}
              incompatibility={firstIncompatibility}
            />
            {incompatibilities.length > 1 ? (
              <Dropdown
                anchor={
                  <Anchor className={styles.showAllIncompatibilitiesButton}>{'show all'}</Anchor>
                }
              >
                <Popup
                  directions={INCOMPATIBILITIES_POPUP_DIRECTIONS}
                  className={styles.incompatibilitiesPopup}
                >
                  {incompatibilities.map(incompatibility =>
                    incompatibility != null ? (
                      <AgentBuildTypeIncompatibility
                        key={JSON.stringify(incompatibility)}
                        className={styles.incompatibilityLine}
                        incompatibility={incompatibility}
                      />
                    ) : null,
                  )}
                </Popup>
              </Dropdown>
            ) : null}
          </>
        ) : null}
      </div>
      {onAssign != null ? (
        <Button
          inline
          className={styles.assignItemButton}
          onClick={e => {
            onAssign(node)
            e.stopPropagation()
          }}
        >
          {'Assign'}
        </Button>
      ) : null}
      {onUnassign != null && assigned === true && onAssign == null ? (
        <Button
          inline
          className={styles.assignItemButton}
          onClick={e => {
            onUnassign(node)
            e.stopPropagation()
          }}
        >
          {'Unassign'}
        </Button>
      ) : null}
    </div>
  )
}

type AgentBuildTypesTreeProps = {
  flatTree: AgentBuildTypesFlatTree
  onToggleExpand: (arg0: {id: string; expanded: boolean}) => void
  assignAll?: (arg0: void) => void
  unassignAll?: (arg0: void) => void
  assignProject?: (node: AgentBuildTypesTreeProjectItem) => void
  unassignProject?: (node: AgentBuildTypesTreeProjectItem) => void
  assignBuildType?: (node: AgentBuildTypesTreeBuildTypeItem) => void
  unassignBuildType?: (node: AgentBuildTypesTreeBuildTypeItem) => void
}
export default function AgentBuildTypesTree({
  flatTree,
  onToggleExpand,
  assignProject,
  unassignProject,
  assignBuildType,
  unassignBuildType,
}: AgentBuildTypesTreeProps) {
  return (
    <>
      {flatTree.map(node =>
        node.type === 'project' ? (
          <AgentBuildTypesTreeProject
            key={node.uniqueId}
            node={node}
            onToggleExpand={onToggleExpand}
            onAssign={assignProject}
            onUnassign={unassignProject}
          />
        ) : (
          <AgentBuildType
            key={node.uniqueId}
            node={node}
            onAssign={assignBuildType}
            onUnassign={unassignBuildType}
          />
        ),
      )}
    </>
  )
}
